// Paramètres documentés de l’API Recherche d’entreprises.
// code_postal cible les établissements ; activite_principale cible l’unité légale.
const criteres = {
  code_postal: '44000',
  activite_principale: '62.01Z',
  etat_administratif: 'A',
  per_page: 25,
  ville_reference: 'Nantes',
  source_api: 'https://recherche-entreprises.api.gouv.fr/search',
  source_annuaire: 'Annuaire des entreprises — données publiques',
  regles: {
    per_page_maximum: 25,
    selection: 'matching_etablissements avec le code postal demandé ; jamais le siège par défaut',
    enrichissement: 'aucun enrichissement réseau, aucune adresse e-mail inventée'
  }
};

return [{ json: criteres }];

// Réponse de l’API : on ne consulte que les champs publics reçus.
// Aucun repli vers `siege` : un établissement doit figurer dans matching_etablissements.
const reponse = $input.first()?.json ?? {};
const criteres = $('Configurer les critères publics').first().json;
const resultats = Array.isArray(reponse.results) ? reponse.results : [];
const codePostal = String(criteres.code_postal || '');
const villeReference = String(criteres.ville_reference || '').trim().toLocaleUpperCase('fr-FR');
const dejaVu = new Set();
const prospects = [];

const texte = (valeur) => String(valeur ?? '').trim();
const sansAccents = (valeur) => texte(valeur)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLocaleUpperCase('fr-FR');
const estSiren = (valeur) => /^\d{9}$/.test(valeur);
const adressePublique = (etablissement) => {
  if (texte(etablissement.adresse)) return texte(etablissement.adresse);
  return [
    etablissement.numero_voie,
    etablissement.indice_rep,
    etablissement.type_voie,
    etablissement.libelle_voie,
    etablissement.code_postal,
    etablissement.libelle_commune
  ].map(texte).filter(Boolean).join(' ');
};

for (const entreprise of resultats) {
  const siren = texte(entreprise.siren).replace(/\D/g, '');
  if (!estSiren(siren) || dejaVu.has(siren) || prospects.length >= 25) continue;

  const etablissements = Array.isArray(entreprise.matching_etablissements)
    ? entreprise.matching_etablissements
    : [];
  const auBonCodePostal = etablissements.filter((etablissement) =>
    texte(etablissement.code_postal) === codePostal
  );
  // La ville ne sert que de préférence parmi les établissements déjà au bon code postal.
  // Ainsi, le workflow ne déduit jamais la localisation depuis le siège de l’unité légale.
  const dansVilleReference = auBonCodePostal.filter((etablissement) =>
    sansAccents(etablissement.libelle_commune) === sansAccents(villeReference)
  );
  const etablissement = dansVilleReference[0] || auBonCodePostal[0];
  if (!etablissement) continue;

  dejaVu.add(siren);
  prospects.push({
    siren,
    denomination: texte(entreprise.nom_complet || entreprise.nom_raison_sociale),
    activite_principale: texte(entreprise.activite_principale),
    etablissement_geographique: {
      siret: texte(etablissement.siret),
      code_postal: texte(etablissement.code_postal),
      ville: texte(etablissement.libelle_commune),
      adresse_publique: adressePublique(etablissement),
      selection: 'matching_etablissements'
    },
    source: {
      libelle: criteres.source_annuaire,
      url: `https://annuaire-entreprises.data.gouv.fr/entreprise/${siren}`
    },
    limites: 'Données publiques uniquement ; pas d’e-mail, pas d’enrichissement réseau supplémentaire.'
  });
}

return prospects.map((prospect) => ({ json: prospect }));
